<span class="line"><span style="color:#839496;">            allowed </span><span style="color:#859900;">=</span><span style="color:#839496;"> [way </span><span style="color:#859900;">for</span><span style="color:#839496;"> way </span><span style="color:#859900;">in</span><span style="color:#268BD2;"> range</span><span style="color:#839496;">(</span><span style="color:#D33682;">4</span><span style="color:#839496;">) </span><span style="color:#859900;">if</span><span style="color:#839496;"> mask </span><span style="color:#859900;">&amp;</span><span style="color:#839496;"> (</span><span style="color:#D33682;">1</span><span style="color:#859900;"> &lt;&lt;</span><span style="color:#839496;"> way)]</span></span>
